  1→<!--
  2→  AC: @ui-task-board ac-1 — Kanban board with columns
  3→  AC: @ui-task-board ac-2 — Task cards with metadata
  4→  AC: @ui-task-board ac-3 — Detail modal on click
  5→  AC: @ui-task-board ac-4 — Active Fleet row
  6→  AC: @ui-task-board ac-5 — Real-time WebSocket updates
  7→  AC: @ui-task-board ac-6 — Task action buttons in modal
  8→-->
  9→<script lang="ts">
 10→	import { page } from '$app/stores';
 11→	import { onMount, onDestroy } from 'svelte';
 12→	import type { TaskSummary, BroadcastEvent } from '@kynetic-ai/shared';
 13→	import { fetchTasks, fetchAgentStatus, type AgentDispatchStatus } from '$lib/api';
 14→	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 15→	import { getProjectVersion } from '$lib/stores/project.svelte';
 16→	import { distributeToColumns, type BoardColumn } from '$lib/components/board/board-utils';
 17→	import BoardColumnComponent from '$lib/components/board/BoardColumn.svelte';
 18→	import ActiveFleetRow from '$lib/components/board/ActiveFleetRow.svelte';
 19→	import TaskDetailModal from '$lib/components/board/TaskDetailModal.svelte';
 20→	import BoardSkeleton from '$lib/components/board/BoardSkeleton.svelte';
 21→	import {
 22→		createSessionState,
 23→		processTextChunk,
 24→		processToolCallStart,
 25→		processToolCallEnd,
 26→		type FleetSessionState,
 27→		type ToolCallIndicator,
 28→	} from '$lib/components/board/fleet-buffer';
 29→	import LayoutGrid from '@lucide/svelte/icons/layout-grid';
 30→	import List from '@lucide/svelte/icons/list';
 31→	import { Button } from '$lib/components/ui/button';
 32→	import { base } from '$app/paths';
 33→
 34→	let tasks = $state<TaskSummary[]>([]);
 35→	let columns = $state<BoardColumn[]>([]);
 36→	let loading = $state(true);
 37→	let error = $state('');
 38→	let agentStatus = $state<AgentDispatchStatus | null>(null);
 39→
 40→	// AC: @ui-task-board ac-4 — Buffered output state per agent session
 41→	let sessionStates = $state<Record<string, FleetSessionState>>({});
 42→
 43→	// Derived: output lines per session (for ActiveFleetRow)
 44→	let agentOutputLines = $derived<Record<string, string[]>>(
 45→		Object.fromEntries(
 46→			Object.entries(sessionStates).map(([id, s]) => [id, s.lines])
 47→		)
 48→	);
 49→
 50→	// Derived: active tool calls per session (for ActiveFleetRow)
 51→	let agentToolCalls = $derived<Record<string, ToolCallIndicator | null>>(
 52→		Object.fromEntries(
 53→			Object.entries(sessionStates).map(([id, s]) => [id, s.activeTool])
 54→		)
 55→	);
 56→
 57→	// AC: @ui-task-board ac-4 — Lookup map: task_ref (@ULID or @slug) → title
 58→	let taskTitles = $derived(
 59→		Object.fromEntries(
 60→			tasks.flatMap((t) => {
 61→				const entries: [string, string][] = [
 62→					[`@${t._ulid}`, t.title]
 63→				];
 64→				for (const slug of t.slugs) {
 65→					entries.push([`@${slug}`, t.title]);
 66→				}
 67→				return entries;
 68→			})
 69→		)
 70→	);
 71→
 72→	// Detail modal state
 73→	let modalOpen = $state(false);
 74→	let selectedTaskRef = $state<string | null>(null);
 75→
 76→	// Track last processed URL ref to avoid infinite loops
 77→	let lastProcessedRef = $state('');
 78→
 79→	$effect(() => {
 80→		// Re-derive columns whenever tasks change
 81→		columns = distributeToColumns(tasks);
 82→	});
 83→
 84→	// AC: @ui-task-board ac-5 — Reload on project change
 85→	$effect(() => {
 86→		const version = getProjectVersion();
 87→		if (version > 0) {
 88→			loadBoard();
 89→		}
 90→	});
 91→
 92→	// Open task detail from URL param
 93→	$effect(() => {
 94→		const urlRef = $page.url.searchParams.get('ref');
 95→		if (urlRef && urlRef !== lastProcessedRef) {
 96→			lastProcessedRef = urlRef;
 97→			selectedTaskRef = urlRef;
 98→			modalOpen = true;
 99→		}
100→	});
101→
102→	async function loadBoard() {
103→		loading = true;
104→		error = '';
105→		try {
106→			const [taskResponse, statusResponse] = await Promise.all([
107→				fetchTasks({ limit: 500 }),
108→				fetchAgentStatus().catch(() => null)
109→			]);
110→			tasks = taskResponse.items;
111→			agentStatus = statusResponse;
112→		} catch (err) {
113→			error = err instanceof Error ? err.message : 'Failed to load board';
114→		} finally {
115→			loading = false;
116→		}
117→	}
118→
119→	function handleCardClick(task: TaskSummary) {
120→		selectedTaskRef = task._ulid;
121→		modalOpen = true;
122→	}
123→
124→	function handleTaskUpdated() {
125→		loadBoard();
126→	}
127→
128→	// AC: @ui-task-board ac-5 — WebSocket real-time updates
129→	function handleTaskUpdate(event: BroadcastEvent) {
130→		loadBoard();
131→	}
132→
133→	// AC: @ui-task-board ac-4 — Refresh agent status on agent events
134→	function handleAgentUpdate(event: BroadcastEvent) {
135→		// AC: @ui-task-board ac-4 — Buffer text chunks into complete lines
136→		if (event.event === 'agent_text_chunk' && event.data?.session_id && event.data?.text) {
137→			const sessionId = event.data.session_id as string;
138→			const text = event.data.text as string;
139→			const current = sessionStates[sessionId] ?? createSessionState();
140→			sessionStates[sessionId] = processTextChunk(current, text);
141→			return;
142→		}
143→
144→		// AC: @ui-task-board ac-4 — Track tool call start for tool indicator
145→		if (event.event === 'agent_tool_call' && event.data?.session_id) {
146→			const sessionId = event.data.session_id as string;
147→			const toolName = (event.data.tool ?? event.data.name ?? 'unknown') as string;
148→			const input = event.data.input ?? event.data.rawInput;
149→			const current = sessionStates[sessionId] ?? createSessionState();
150→			sessionStates[sessionId] = processToolCallStart(current, toolName, input);
151→			return;
152→		}
153→
154→		// AC: @ui-task-board ac-4 — Clear tool indicator on tool completion
155→		if (event.event === 'agent_tool_result' && event.data?.session_id) {
156→			const sessionId = event.data.session_id as string;
157→			const current = sessionStates[sessionId];
158→			if (current) {
159→				sessionStates[sessionId] = processToolCallEnd(current);
160→			}
161→			return;
162→		}
163→
164→		// Invocation lifecycle events — refresh status and clean up stale state
165→		fetchAgentStatus()
166→			.then((status) => {
167→				agentStatus = status;
168→				// Clean up session states for sessions no longer active
169→				const activeSessions = new Set(
170→					status.active_invocations.map((inv) => inv.session_id)
171→				);
172→				for (const sessionId of Object.keys(sessionStates)) {
173→					if (!activeSessions.has(sessionId)) {
174→						delete sessionStates[sessionId];
175→					}
176→				}
177→			})
178→			.catch(() => {});
179→	}
180→
181→	// Polling for agent elapsed time updates
182→	let agentPollTimer: ReturnType<typeof setInterval> | undefined;
183→
184→	onMount(() => {
185→		loadBoard();
186→
187→		// AC: @ui-task-board ac-5 — Subscribe to task and agent updates
188→		subscribe(['tasks', 'agents']);
189→		on('tasks', handleTaskUpdate);
190→		on('agents', handleAgentUpdate);
191→
192→		// Poll agent status every 5s for elapsed time updates
193→		agentPollTimer = setInterval(() => {
194→			fetchAgentStatus()
195→				.then((status) => {
196→					agentStatus = status;
197→				})
198→				.catch(() => {});
199→		}, 5000);
200→	});
201→
202→	onDestroy(() => {
203→		off('tasks', handleTaskUpdate);
204→		off('agents', handleAgentUpdate);
205→		unsubscribe(['tasks', 'agents']);
206→		if (agentPollTimer) clearInterval(agentPollTimer);
207→	});
208→</script>
209→
210→<div class="flex flex-col h-full">
211→	<!-- Header -->
212→	<div class="flex items-center justify-between p-6 pb-0">
213→		<div>
214→			<h1 class="text-2xl font-bold">Task Board</h1>
215→			{#if !loading && tasks.length > 0}
216→				<p class="text-sm text-muted-foreground">{tasks.length} tasks</p>
217→			{/if}
218→		</div>
219→
220→		<!-- View toggle: Board / List -->
221→		<div class="flex items-center gap-1 border rounded-lg p-0.5">
222→			<Button
223→				variant="ghost"
224→				size="icon-sm"
225→				class="bg-accent"
226→				title="Board view"
227→				aria-pressed="true"
228→			>
229→				<LayoutGrid class="size-4" />
230→			</Button>
231→			<a href="{base}/tasks" title="List view">
232→				<Button variant="ghost" size="icon-sm" aria-pressed="false">
233→					<List class="size-4" />
234→				</Button>
235→			</a>
236→		</div>
237→	</div>
238→
239→	<!-- Error -->
240→	{#if error}
241→		<div class="mx-6 mt-4 bg-destructive/10 text-destructive p-4 rounded-lg" role="alert" data-testid="board-error">
242→			{error}
243→		</div>
244→	{/if}
245→
246→	<!-- Loading skeleton -->
247→	{#if loading}
248→		<BoardSkeleton />
249→	{:else if tasks.length === 0}
250→		<!-- Empty state -->
251→		<div class="flex flex-col items-center justify-center flex-1 py-16" data-testid="board-empty">
252→			<LayoutGrid class="size-12 text-muted-foreground/30 mb-4" />
253→			<h2 class="text-lg font-medium text-muted-foreground mb-1">No tasks yet</h2>
254→			<p class="text-sm text-muted-foreground">
255→				Create tasks using <code class="bg-muted px-1 rounded text-xs">kspec task add</code>
256→			</p>
257→		</div>
258→	{:else}
259→		<!-- AC: @ui-task-board ac-4 — Active Fleet Row -->
260→		<div class="px-6 pt-4">
261→			<ActiveFleetRow status={agentStatus} outputLines={agentOutputLines} toolCalls={agentToolCalls} {taskTitles} />
262→		</div>
263→
264→		<!-- AC: @ui-task-board ac-1 — Kanban Columns -->
265→		<div class="flex gap-4 overflow-x-auto p-6 pt-2 flex-1 min-h-0" data-testid="board-columns">
266→			{#each columns as column (column.id)}
267→				<BoardColumnComponent {column} onCardClick={handleCardClick} />
268→			{/each}
269→		</div>
270→	{/if}
271→</div>
272→
273→<!-- AC: @ui-task-board ac-3, ac-6 — Detail Modal -->
274→<TaskDetailModal
275→	bind:open={modalOpen}
276→	bind:taskRef={selectedTaskRef}
277→	onTaskUpdated={handleTaskUpdated}
278→/>
